import{_ as r,y as n,a as o,o as a,ag as t,D as i}from"./chunks/framework.C2qfZH9T.js";const _=JSON.parse('{"title":"RGPD","description":"","frontmatter":{},"headers":[],"relativePath":"configure/gdpr.md","filePath":"configure/gdpr.md","lastUpdated":1782937842000}'),l={name:"configure/gdpr.md"};function c(p,e,d,u,g,m){const s=n("ImagePopup");return a(),o("div",null,[e[0]||(e[0]=t('<h1 id="rgpd" tabindex="-1">RGPD <a class="header-anchor" href="#rgpd" aria-label="Permalink to &quot;RGPD&quot;">​</a></h1><p>ExalandStore fournit des fonctionnalités essentielles de conformité au RGPD (Règlement Général sur la Protection des Données) pour aider les entreprises à garantir la confidentialité et la transparence des données de leurs clients. Vous trouverez ci-dessous les principales sections dans lesquelles les paramètres et options liés au RGPD sont disponibles :</p><h2 id="activer-les-parametres-de-conformite-rgpd" tabindex="-1">Activer les paramètres de conformité RGPD <a class="header-anchor" href="#activer-les-parametres-de-conformite-rgpd" aria-label="Permalink to &quot;Activer les paramètres de conformité RGPD&quot;">​</a></h2><p>Pour ajouter, allez dans le panneau d&#39;administration et cliquez sur <strong>Configurer &gt;&gt; RGPD &gt;&gt; Activer le RGPD</strong>. Cette section permet aux propriétaires de magasins de configurer les politiques liées au RGPD et de gérer efficacement les demandes de données des clients. Les principales fonctionnalités incluent :</p><ul><li>Le bouton <strong>Demande RGPD</strong> apparaît sur la page de profil du client dans l&#39;interface du magasin.</li><li>Traiter les demandes des clients pour la suppression ou la mise à jour des données.</li></ul>',5)),i(s,{src:"/images/configure/gdpr-agreement.png",alt:"Enable GDPR Compliance Settings"}),e[1]||(e[1]=t(' <p>Après cela, cliquez sur le bouton <strong>Enregistrer la configuration</strong>.</p><h2 id="accord-rgpd" tabindex="-1">Accord RGPD <a class="header-anchor" href="#accord-rgpd" aria-label="Permalink to &quot;Accord RGPD&quot;">​</a></h2><p>Pour ajouter, accédez au panneau d&#39;administration et cliquez sur <strong>Configurer &gt;&gt; RGPD &gt;&gt; Activer le contrat client</strong>. Le bouton Accord RGPD est utilisé pour obtenir le consentement explicite des clients avant de procéder à l&#39;enregistrement du compte, au paiement ou à d&#39;autres actions liées aux données. Il assure :</p><ul><li>Les utilisateurs reconnaissent et acceptent la politique de confidentialité de la boutique.</li><li>Le consentement est enregistré pour la conformité légale.</li></ul><p>Champs à renseigner dans la section Accord RGPD :</p><ul><li><strong>Étiquette de case à cocher d&#39;accord</strong> – J&#39;accepte les termes et conditions et la politique de confidentialité.</li><li><strong>Contenu de l&#39;accord</strong> – En cochant cette case, vous consentez au traitement de vos données personnelles conformément à notre politique de confidentialité conforme au RGPD.</li></ul>',7)),i(s,{src:"/images/configure/gdpr-agreement2.png",alt:"GDPR Agreement Settings"}),e[2]||(e[2]=t(' <p>Après cela, cliquez sur le bouton <strong>Enregistrer la configuration</strong>.</p><h2 id="parametres-d-avis-de-cookies" tabindex="-1">Paramètres d&#39;avis de cookies <a class="header-anchor" href="#parametres-d-avis-de-cookies" aria-label="Permalink to &quot;Paramètres d&#39;avis de cookies&quot;">​</a></h2><p>Pour ajouter, accédez au panneau d&#39;administration et cliquez sur <strong>Configurer &gt;&gt; RGPD &gt;&gt; Activer l&#39;avis sur les cookies</strong>. Cette section permet aux propriétaires de magasins de configurer la manière dont l&#39;avis de cookie apparaît aux utilisateurs. Les paramètres clés incluent :</p><ul><li><p><strong>Position d&#39;affichage du bloc de cookies</strong> – Détermine où l&#39;avis de cookie apparaîtra sur la page. Options disponibles :</p></li><li><p>En bas à gauche</p></li><li><p>En bas à droite</p></li><li><p>En haut à gauche</p></li><li><p>En haut à droite</p></li><li><p>Centre</p></li><li><p><strong>Static Block Identifier</strong> – Spécifie un bloc statique personnalisé à afficher dans l&#39;avis de cookie.</p></li><li><p><strong>Description</strong> – Un champ de texte personnalisable pour décrire l&#39;objectif des cookies, les détails de confidentialité et la manière dont les utilisateurs peuvent gérer leurs préférences.</p></li></ul>',5)),i(s,{src:"/images/configure/cookies-position.png",alt:"Cookie Notice Settings"}),e[3]||(e[3]=t(' <p>Après cela, cliquez sur le bouton <strong>Enregistrer la configuration</strong>.</p><h2 id="gerez-vos-preferences-en-matiere-de-cookies" tabindex="-1">Gérez vos préférences en matière de cookies <a class="header-anchor" href="#gerez-vos-preferences-en-matiere-de-cookies" aria-label="Permalink to &quot;Gérez vos préférences en matière de cookies&quot;">​</a></h2><p>Cette section permet aux utilisateurs de personnaliser leurs paramètres de cookies en fonction de leurs préférences. Les catégories disponibles incluent :</p><ul><li><p><strong>Strictement nécessaire</strong> – Cookies essentiels nécessaires au bon fonctionnement du site Web, tels que la gestion de session et les fonctionnalités de sécurité. Ne peut pas être désactivé.</p></li><li><p><strong>Interactions et fonctionnalités de base</strong> – Prend en charge les interactions des utilisateurs, telles que les fonctionnalités de chat, les soumissions de formulaires et les améliorations de la navigation.</p></li><li><p><strong>Améliorations de l&#39;expérience</strong> – Améliorez l&#39;expérience utilisateur en mémorisant les préférences, telles que la sélection de la langue ou les mises en page personnalisées.</p></li><li><p><strong>Mesures</strong> – Cookies d&#39;analyse pour suivre les performances du site Web, le comportement des utilisateurs et les informations sur le trafic à des fins d&#39;optimisation.</p></li><li><p><strong>Ciblage et publicité</strong> – Cookies utilisés pour le marketing personnalisé, le ciblage publicitaire et le reciblage en fonction du comportement et des préférences de l&#39;utilisateur.</p></li></ul><p>Après cela, cliquez sur le bouton <strong>Enregistrer la configuration</strong>.</p>',6))])}const P=r(l,[["render",c]]);export{_ as __pageData,P as default};
